private CoordinationGroupResponse doRegisterCoordinationGroup(CoordinationGroupRequest request) {
    long currentVersion = repositoryDao.lockRepositoryState(); // already locked; returns version
    if (currentVersion != request.expectedRepositoryVersion()) throw 409
    String groupName = request.groupName().trim();
    List<String> members = sortedMembers(request);
    List<Map<String,Integer>> tuples = canonicalTuples(request); // sorted list of TreeMaps
