private void validateCoordinationGroupRequest(CoordinationGroupRequest request) {
    if (request.groupName() == null || request.groupName().isBlank()) 400 "groupName 不能为空"
    if (request.operator() == null || request.operator().isBlank()) 400 "operator 不能为空"
    List<String> members = request.members();
    if (members == null || members.size() < 2 || members.size() > 4) 400 "协调组成员数量须为 2 至 4"
    Set<String> distinct = new HashSet<>();
    for (String m : members) {
        if (m == null || m.isBlank()) 400 "成员名称不能为空"
        String name = m.trim();
        if (name.chars().anyMatch(c -> c==','||c==';'||c=='=')) 400 "成员名称不能包含 , ; = 字符"
        if (!distinct.add(name)) 400 "成员名称重复: "
    }
    List<...> tuples = request.allowedTuples();
    if (tuples == null || tuples.isEmpty() || tuples.size() > 5) 400 "允许元组数量须为 1 至 5"
    Set<String> seen = new HashSet<>();
    for (Map<String,Integer> tuple : tuples) {
        if (tuple == null) 400
        // keys trimmed == member set
        Map<String,Integer> normalized = new TreeMap<>(); tuple.forEach((k,v)->{ if(k!=null) normalized.put(k.trim(), v);});
        if (tuple contains null key or blank key) 400
        if (!normalized.keySet().equals(distinct)) 400 "元组必须完整列出全部成员版本"
        for value: if (v == null || v < 1) 400 "元组版本必须为正整数"
        if (!seen.add(CoordinationTuples.canonicalTuple(normalized))) 400 "允许元组重复"
    }
}
